-- Schema-only catalog fixture captured from production before release alignment.
-- No tenant data, credentials, function bodies, or snapshots are included.
CREATE TYPE public.app_role AS ENUM ('owner','admin','member','viewer');
CREATE TYPE public.po_status AS ENUM ('draft','approved','partial','received','closed','cancelled');
CREATE TYPE public.invoice_status AS ENUM ('draft','matched','exception','approved','paid','cancelled');
CREATE TYPE public.order_status AS ENUM ('draft','confirmed','shipped','delivered','cancelled');
CREATE TYPE public.account_type AS ENUM ('asset','liability','equity','revenue','expense');
CREATE TYPE public.quote_status AS ENUM ('draft','sent','accepted','rejected','expired');
CREATE TYPE public.shipment_status AS ENUM ('pending','packed','shipped','delivered','cancelled');
CREATE TYPE public.payment_status AS ENUM ('unpaid','partial','paid','refunded');
CREATE TYPE public.tenant_status AS ENUM ('active','frozen','deleted');
CREATE TYPE public.sales_invoice_status AS ENUM ('draft','issued','partial','paid','overdue','cancelled');
CREATE TABLE public.projects (id uuid,user_id uuid,name text,description text,status text,budget numeric(14,2),start_date date,end_date date,created_at timestamp with time zone,updated_at timestamp with time zone,tenant_id uuid);
CREATE TABLE public.tenants (id uuid,name text,slug text,created_by uuid,created_at timestamp with time zone,updated_at timestamp with time zone,status tenant_status,max_users integer,plan_name text,expires_at date,notes text,frozen_at timestamp with time zone,deleted_at timestamp with time zone);
CREATE TABLE public.tenant_members (id uuid,tenant_id uuid,user_id uuid,role app_role,created_at timestamp with time zone);
